INSERT INTO `email_notifications` VALUES (1,'11067','ruchiranjana@gmail.com','Re: Payscale Revision | May 25 | Ms Ruchi Sarangi','Dear Nitin,\n\n I would like to sincerely thank you for the recent revision to my pay\nscale. I truly appreciate the recognition of my contributions  for the\nOrganization.\n This gesture reinforces my motivation to contribute even more effectively\nto our shared goals and responsibilities.\n\n\nRegards,\nRuchi Sarangi\n\nOn Fri, May 30, 2025 at 5:17 PM Funstay HR <hr@funstay.in> wrote:\n\n>  Dear Ruchi,\n>\n> Congratulations! We are pleased to inform you that your payscale has been\n> revised and will be effective from 1st May 2025\n>\n> Thanks for being part of the Funstay Family and we hope you will continue\n> to move ahead on the path of excellence. A copy of the pay scale revision\n> letter is attached for your records.\n>\n> Thanks and Regards,\n> Funstay HR Team\n>','2025-05-31 05:02:18',NULL,NULL,NULL,'admin','2025-06-10 09:16:26'),(2,'11067','ruchiranjana@gmail.com','Re: Payscale Revision | May 25 | Ms Ruchi Sarangi','Dear Nitin,\n\n I would like to sincerely thank you for the recent revision to my pay\nscale. I truly appreciate the recognition of my contributions  for the\nOrganization.\n This gesture reinforces my motivation to contribute even more effectively\nto our shared goals and responsibilities.\n\n\nRegards,\nRuchi Sarangi\n\nOn Fri, May 30, 2025 at 5:17 PM Funstay HR <hr@funstay.in> wrote:\n\n>  Dear Ruchi,\n>\n> Congratulations! We are pleased to inform you that your payscale has been\n> revised and will be effective from 1st May 2025\n>\n> Thanks for being part of the Funstay Family and we hope you will continue\n> to move ahead on the path of excellence. A copy of the pay scale revision\n> letter is attached for your records.\n>\n> Thanks and Regards,\n> Funstay HR Team\n>','2025-05-31 05:02:18',NULL,NULL,'52',NULL,'2025-06-10 09:16:26'),(3,'11067','ruchiranjana@gmail.com','Re: Payscale Revision | May 25 | Ms Ruchi Sarangi','Dear Nitin,\n\n I would like to sincerely thank you for the recent revision to my pay\nscale. I truly appreciate the recognition of my contributions  for the\nOrganization.\n This gesture reinforces my motivation to contribute even more effectively\nto our shared goals and responsibilities.\n\n\nRegards,\nRuchi Sarangi\n\nOn Fri, May 30, 2025 at 5:17 PM Funstay HR <hr@funstay.in> wrote:\n\n>  Dear Ruchi,\n>\n> Congratulations! We are pleased to inform you that your payscale has been\n> revised and will be effective from 1st May 2025\n>\n> Thanks for being part of the Funstay Family and we hope you will continue\n> to move ahead on the path of excellence. A copy of the pay scale revision\n> letter is attached for your records.\n>\n> Thanks and Regards,\n> Funstay HR Team\n>','2025-05-31 05:02:18',NULL,'32',NULL,NULL,'2025-06-10 09:16:26'),(4,'11576','booking@funstay.in','Request to Accommodate 2 Adults and 2 Children in One Room – Booking ID: NH25238408958710','Dear Team,\n\nGreetings from Funstay, Bangalore!\n\nWe are writing to you regarding a reservation made vide Booking ID: NH25238408958710 for a Triple Room with Double Bed at esteemed property for Mr Deepak Divakara Kammath\n\nThe booking has currently been made for 2 adults and 1 child (09 years old). However, we would like to kindly request you to allow 2 adults and 2 children (ages 09 and 05) to be accommodated in the same room.\n\nDue to system limitations on the online portal, any addition of the second child reflects a requirement for two separate rooms, which is not feasible in our case, as both children are young and the family prefers to stay together in one room. The younger child, aged 5, can comfortably share the existing double bed with the parents and does not require an additional bed setup.\n\nWe kindly request your understanding and support in accommodating this request as a one-time exception, considering the comfort and safety of the family.\n\nLooking forward to your positive resp