INSERT INTO `emails` VALUES (1,'Qu001','roxannebulsara@gmail.com','Quotation #Qu001','Please find the attached quotation.','/uploads/file-1743084307439.pdf','2025-03-27 14:05:14','sent',NULL,'10732',1,NULL,NULL,NULL),(2,NULL,'for.na05@gmail.com','hello','<p>gfyguyhk</p>',NULL,'2025-05-29 14:01:43','sent','<1a1e8ad7-5cef-79e9-a6e7-52612fa3d0b8@funstay.in>','11538',1,'mahim.mehta@funstay.in',NULL,NULL),(3,NULL,'ruchiranjana@gmail.com','Follow up Mail','<p>Hi</p>',NULL,'2025-05-30 09:37:32','sent','<b54b4859-048b-8959-ab08-cd7f99f07520@funstay.in>','11067',1,'ruchi.sarangi@funstay.in',NULL,NULL),(4,NULL,'jayjarugula@gmail.com','Appreciation email for your hard work','<p>Hi Jay,</p><p>You are doing an excellent work at the office with dedication &amp; determinati</p>',NULL,'2025-05-30 09:38:20','sent','<2189781b-36bc-5e77-54d1-094bb6ed509c@funstay.in>','11543',1,'jayadeep.jarugula@funstay.in',NULL,NULL),(5,NULL,'vasantrander1206@gmail.com','11386 l Singapore & Malaysia l Basant l 2 Adults 2 Child l 20 Sep - 28 Sep','<p class=\"ql-align-center\"><br></p>',NULL,'2025-05-30 09:38:34','sent','<b375e31d-1457-cb87-92b1-2166773826b2@funstay.in>','11386',1,'jai.chandra@funstay.in',NULL,NULL),(6,NULL,'mic.richie007@gmail.com','11535 l 4N5D Marvellous Maldives l Micheal Richard l 2 Adults l 20-24 Aug 2025 l Follow-up','<p>Hi Micheal,</p><p><br></p><p>!!!Greetings from Funstay!!!</p><p><br></p><p>Please let me know if there is any update on the package for your Maldives package. Also let me know if you have doubts or want any changes.</p><p><br></p><p>Thank You!</p>',NULL,'2025-05-30 09:39:30','sent','<05de1e21-f7af-4e35-5f8e-533d94254b90@funstay.in>','11535',1,'puspak.das@funstay.in',NULL,NULL),(7,NULL,'udaysree81@gmail.com','SING & MAL','<p>Dear Udayasree,</p><p><br></p><p>i am writing this mail to let you know that I have curated the package below</p>',NULL,'2025-05-30 09:40:00','sent','<39f3a80f-4252-b7ab-f24e-eb488dffb16b@funstay.in>','11537',1,'chaithanya.as@funstay.in',NULL,NULL),(8,NULL,'clintrocks4u@gmail.com','Trip ID 11544 l 7N8D Blissful Bali l Clint l 4 Pax l 5th to 12th July 2025','<p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXfERepOBkY_8Ss_Vd3tnvqjon3zZnwDUp9oNMVAZFxFAXd-wlkQyB4pr2sr3OvLx4ecgh2BqsaLjKaFNLxKaCGnQw-nB9Xx6IVBpOZ278NAyTbBupLgV1gSj0_iWc2uQ--MQrsGb-MypiTuMLcEv64?key=H-BwDgy9xr8m2oQBY7URfQ\" height=\"174\" width=\"668\"></span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Dear Clint,</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Greetings from Funstay.in and thank you for your interest in Funstay’s travel services.</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Funstay Services Pvt Ltd is an experiential travel service provider based out of Bengaluru, India. It also owns &amp; operates Funstay.in, the online booking platform for experiential travel services tailored around unique and niche stays. With over 2000 properties across 100+ location across India, Funstay is one of the pioneers in this segment and is also amongst the fastest growing company in experiential travel segment in India.&nbsp;</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">To understand more about Funstay, visit&nbsp;</span><a href=\"http://www.funstay.in/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"background-color: transparent; color: rgb(0, 0, 0);\">www.funstay.in</a><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">&nbsp;,&nbsp;you can also go through our reviews at&nbsp;</span><a href=\"https://www.facebook.com/pg/funstay.in/reviews/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"background-color: transparent; color: rgb(0, 0, 0);\">Facebook</a><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">&nbsp;or&nbsp;</span><a href=\"https://www.google.com/maps/place/Funstay+Services+Pvt+Ltd+-+Homestay+in+Coorg,+Ooty,+Ladakh,+Andaman+Tour+Packages/@12.9085926,77.649664,15z/data=!4m7!3m6!1s0x0:0xf78d7e9aae2673f5!8m2!3d12.9085922!4d77.6496725!9m1!1b1\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"background-color: transparent; color: rgb(0, 0, 0);\">Google</a><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">.</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">We are pleased to share below offers for your planned holiday in Bali as below,</span></p><p><br></p><p><strong style=\"background-color: transparent; color: rgb(255, 0, 0);\">TRAVEL DETAILS</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Check in Date: 5th July 2025</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Check out Date: 12th July 2025</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">No of Nights: 7N8D</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">No of Guest: 4 Adults</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">No of Rooms: 2</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Meal Plan: Breakfast Included</span></p><p><br></p><p><strong style=\"background-color: rgb(255, 255, 0); color: rgb(255, 0, 0);\">4 STAR LAND PACKAGE COST:</strong></p><p><strong style=\"color: rgb(0, 0, 0);\">HOTEL IN UBUD (4 STAR)</strong></p><p><strong style=\"color: rgb(0, 0, 0);\">HOTEL IN KUTA (4 STAR)</strong></p><p><strong style=\"color: rgb(0, 0, 0);\">COST PER PERSON (IN INR)</strong></p><p><span style=\"color: rgb(0, 0, 0);\">4N Ubud Wana Resort</span></p><p><span style=\"color: rgb(0, 0, 0);\">Deluxe Double Room</span></p><p><span style=\"color: rgb(0, 0, 0);\">3N Hotel Vila Lumbung,&nbsp;</span></p><p><span style=\"color: rgb(0, 0, 0);\">Deluxe Lumbung</span></p><p><strong style=\"background-color: rgb(255, 255, 0); color: rgb(0, 0, 0);\">INR 70,000/- + 5%TCS + 5% GST</strong></p><p><br></p><p><strong style=\"color: rgb(255, 0, 0);\">INCLUSIONS&nbsp;</strong></p><p><strong style=\"color: rgb(0, 0, 0);\">HOTEL: </strong><span style=\"color: rgb(0, 0, 0);\">As mentioned above</span></p><p><strong style=\"color: rgb(0, 0, 0);\">MEAL PLAN</strong><span style=\"color: rgb(0, 0, 0);\">: Breakfast Included</span></p><p><strong style=\"color: rgb(0, 0, 0);\">VISA: </strong><span style=\"color: rgb(0, 0, 0);\">e-Visa &amp; Tourism Levy</span></p><p><br></p><p><strong style=\"color: rgb(0, 0, 0);\">TOURS &amp; TRANSFERS: ( All transfers on Private basis)</strong></p><ul><li>Airport Arrival transfer</li><li>Inter hotel transfers</li><li>Departure Transfer between Kuta hotel to the airport</li><li>Kintamani&nbsp;tour&nbsp;with&nbsp;mount&nbsp;batur&nbsp;view&nbsp;point,&nbsp;tegalalang&nbsp;rice&nbsp;terraces,bali swing - Private</li><li>Tirta Gangga &amp; Besakih Great Temple - Private&nbsp;</li><li>Bali Safari &amp; Marine Park- Private&nbsp;</li><li>Kanto Lampo Waterfall - Private&nbsp;</li><li>Half Day Evening Sunset Tanah Lot Tour – Private</li><li><span style=\"color: rgb(33, 33, 33);\">Nusa Penida Tour&nbsp; (Kelingking Beach, Broken Beach, Angel Billabong) with lunch, 2 way ferry- Private</span></li><li><span style=\"color: rgb(33, 33, 33);\">Full Day tour of watersports (banana boat, jet ski, parasailing), and Uluwatu Temple with Kecak Dance</span>- Private</li></ul><p><br></p><p><strong style=\"color: rgb(255, 0, 0);\">EXCLUSIONS&nbsp;</strong></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Airfare </strong><em style=\"background-color: transparent; color: rgb(255, 0, 0);\">(fare at the time of preparation of this quote is Rs 1,11,500/- per person, however it will be booked on actual prevailing fare at the time of confirmation)&nbsp;&nbsp;</em></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXc0X3YgzV5sTMie-69S3-G1clM3ikbP7UZSJS0_8DvZFf4YP4sM0RDOPCK-4iAMNLOgKyo7j0ho3BBw6L14EIChZdYSBAEEOURphcPKJOZ4MTLpNb0uOFMBW3Mn0hp_bOB3zTrz5lGnJlO-HLwxOf8?key=H-BwDgy9xr8m2oQBY7URfQ\" height=\"79\" width=\"231\"></strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">All kinds of personal expenses such as tips, laundry, telephone bills, beverages, etc</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Entrance Tickets.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Any parking &amp; toll charges for a full day private vehicle at disposal</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Any meals &amp; beverages unless and otherwise specifically mentioned</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Additional sightseeing charges or extra usage of vehicle</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Any additional charges arising due to natural calamities, political disturbances, etc</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Anything else not specifically mentioned in the inclusions.</span></p><p><span style=\"background-color: rgb(255, 255, 0); color: rgb(0, 0, 0);\">GST @ 5%</span></p><p><span style=\"background-color: rgb(255, 255, 0); color: rgb(0, 0, 0);\">Mandatory TCS at 5% of Package Cost (as per RBI wef 1st&nbsp;Oct 2020, a TCS of 5% is to be collected for all foreign remittances for travel outside India. A TCS Certificate against the same will be issued to the traveler and the same can be claimed while filing ITR).</span></p><p><br></p><p><strong style=\"color: rgb(255, 0, 0);\">TOUR ITINERARY</strong></p><p><strong style=\"color: rgb(0, 0, 0);\">DAY 1: ARRIVAL AT BALI |TRANSFER TO UBUD | EVENING AT LEISURE&nbsp;</strong></p><p><span style=\"color: rgb(0, 0, 0);\">Welcome to Bali- the Island of Gods!</span></p><p><br></p><p><span style=\"color: rgb(0, 0, 0);\">Upon arrival at Bali, meet and greet at the airport and transfer to your hotel in Ubud. Check-In and some time to rest. The rest of the day is at leisure to explore the area on your own. Overnight at the hotel.</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXf7DgsN_yrp1vx8IUw2qwo60frWlYE84GQlfJS8jnCpXRKyf5rAdCJtqrlLMKMaXqQuF87sSmn-Zn3LAeXimGSjzZXSVhNZ_v96bDVVxiI8iRdLNK-OqS0tcXeCFqLqKv9Pvn2IfwJJjoC2PFPnfnU?key=H-BwDgy9xr8m2oQBY7URfQ\" alt=\"Visit the Monkey Forest in Ubud - Hue Bali\" height=\"376.38723604461296\" width=\"669.6405992372976\"></span></p><p><br></p><p><strong style=\"color: rgb(0, 0, 0);\">DAY 2 KINTAMANI&nbsp;TOUR&nbsp;WITH&nbsp;MOUNT&nbsp;BATUR&nbsp;VIEW&nbsp;POINT|&nbsp;TEGALALANG&nbsp;RICE&nbsp;TERRACES | BALI SWING | UBUD ART MARKET</strong></p><p><span style=\"color: rgb(0, 0, 0);\">After breakfast, time to proceed for the Kintamani Tour. Visit the Mount Batur View Point, Though an active volcano, the last Mount Batur eruption was recorded in 2000. The hike, though an easy climb, is advised to be done with a local guide.</span></p><p><span style=\"color: rgb(0, 0, 0);\">Tegalalang Rice Terraces, Tegalalang Rice Terrace is one of the famous tourist attractions in Bali situated in Tegalalang Village north of Ubud Bali featured by the amazing rice terrace set on the cliff. Tegalalang Village is located 600 m above sea levels covered by good temperature where most of the villagers are farmers.</span></p><p><span style=\"color: rgb(0, 0, 0);\">Overnight stay in the Hotel.</span></p><p><br></p><p><span style=\"color: rgb(0, 0, 0);\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXeBoVtqkIVK7JbH5L4eLqT-EbJdBewTWf-tDi1iHX0taftfvjdEAMmEquG7LzhLW49eQiMAqaikskdCLgv6LEbPkB1bMPFDd--ma1E_m_eoro0x4gFoQkpiNCynhRRhoMpGYeUJL1sCtJ0W6PXlhDE?key=H-BwDgy9xr8m2oQBY7URfQ\" height=\"204\" width=\"319\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXcSG80ZEgIzSP-3Ti_4GetyWzTLR7nOYMhw0dMI5bFpJKv_KuawdUFWpAQ33cmnPbvb6CwgbhVwi0WRubeWi2LEgleAHB-RstARfFtx31Vkni-iIaJVH1WezLo9ThAA0rdab_RLy2ZfnSGPe1dupg?key=H-BwDgy9xr8m2oQBY7URfQ\" height=\"205\" width=\"328\"></span></p><p><br></p><p><strong style=\"color: rgb(0, 0, 0);\">DAY 3: TIRTHA GANGA | BESAKIH&nbsp;</strong></p><p><span style=\"color: rgb(0, 0, 0);\">After breakfast at your hotel, your day will begin with your journey to Tirta Gangga, one of Bali’s most beautiful and peaceful water palaces. Located in the village of Ababi, Tirta Gangga is known for its stunning water gardens, fountains, and statues. The complex is a picturesque maze of stone paths, koi ponds, and lush tropical gardens, creating a perfect place for a leisurely walk. You’ll have time to explore the royal bathing pools and enjoy the peaceful atmosphere of this tranquil setting, which was once the royal water palace of the Karangasem Kingdom.</span></p><p><br></p><p><span style=\"color: rgb(0, 0, 0);\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXdLbOqJxCo0bLagIj3P790XAkIOtwREWQKAvjNEwUod1D_0hQu2Y76NWYgbNxXKSOwNuHRHCrtD1wSswXiZkIbYmNNDFRb9LIZATB6cY5af9BB71o_wgeDKm56xjEKJ1crHnkUuxYom3EnoCqz3uA?key=H-BwDgy9xr8m2oQBY7URfQ\" height=\"285\" width=\"669\"></span></p><p><br></p><p><span style=\"color: rgb(0, 0, 0);\">After lunch (on your own). Next, continue your exploration with a visit to Besakih Temple, Bali’s largest and holiest temple complex, often referred to as the \"Mother Temple\" of Bali. Situated on the majestic slopes of Mount Agung, Besakih Temple consists of over 80 individual temples and is the spiritual center of the island. As you walk through the complex, you’ll be surrounded by grand architecture, ancient statues, and sacred shrines, all offering insight into Balinese Hinduism. From the temple, you’ll also enjoy breathtaking panoramic views of the surrounding landscapes, including lush green valleys and distant mountains. It’s a perfect place to take in the natural beauty of Bali while reflecting on its spiritual heritage.</span></p><p><span style=\"color: rgb(0, 0, 0);\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXdmRtduOZpb6s9JhFI-4ThJo_ckecqa0DwN7oa_x_8jiv8jqmlWrt_1_6Vj4aL4SbJdnJ9mPFisFQ76gLldkmvBHDYIpY591UfVFCNPE_hx28yeLAs2iGcSvaSyfVDt9Icvc3vllrgbM-N2NBU2HA?key=H-BwDgy9xr8m2oQBY7URfQ\" height=\"447.4681980095009\" width=\"669\"></span></p><p><br></p><p><strong style=\"color: rgb(0, 0, 0);\">DAY 7: BALI SAFARI &amp; MARINE PARK</strong></p><p><span style=\"color: rgb(0, 0, 0);\">After breakfast, proceed for the Bali Safari Tour. Bali Safari Park, The African Safari Adventure in Bali. Home to over a thousand amazing animals and your finest destination for an adventurous, fun and educational experience more than just a safari. Our park represents more than 120 species, including rare &amp; endangered species like the Komodo Dragons, Orangutan, Bali Starling bird, and many more. After Bali Safari return to hotel, night at leisure.</span></p><p><span style=\"color: rgb(0, 0, 0);\">&nbsp;</span></p><p><span style=\"color: rgb(0, 0, 0);\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXexS0_Gjw4i6MmrMCP27iVpDKb1zc448v8k4DAeOYejN-ZDy81IUAiZ2WWuSl-BQpRv3VXOq7xeClZR-W5SLCAmOs0XNqrqVW147v_A93E3_kJSXyOmYsvqY8MY-8-ncvC_xOKbR9etHYbmhjamW3w?key=H-BwDgy9xr8m2oQBY7URfQ\" height=\"500.86189503073484\" width=\"669\"></span></p><p><strong style=\"color: rgb(0, 0, 0);\">DAY 5: KANTO LAMPO WATERFALL | TANAH LOT SUNSET | INTER HOTEL TRANSFER&nbsp;</strong></p><p><span style=\"color: rgb(0, 0, 0);\">After breakfast at your hotel before embarking on an exciting visit to Kanto Lampo Waterfall, a hidden gem nestled in the lush jungle of Bali. Known for its unique, tiered formation, this beautiful waterfall allows you to take a refreshing dip in its cool waters or simply enjoy the stunning natural surroundings. The waterfall is less crowded, offering a serene atmosphere to relax and connect with nature.&nbsp;</span></p><p><br></p><p><span style=\"color: rgb(0, 0, 0);\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXcOASB3ppOAJkadGafv5Mg8BjOEtb8jHd4u-Yoe3clxQoO24I58tMQzxaCDgV-61H-TK1Wv1RTlEHyzWwGxp03lTKiNjmtxj2mPlanLwET7jvMQURBYialPgRTGqOpL9rlYE-Awq_asJ3KQfDxKWpY?key=H-BwDgy9xr8m2oQBY7URfQ\" height=\"446.9368454672881\" width=\"669\"></span></p><p><br></p><p><span style=\"color: rgb(0, 0, 0);\">After spending some time at Kanto Lampo, it will be time to head towards Tanah Lot Temple, one of Bali\'s most important landmarks, famed for its unique offshore setting and sunset backdrops. An ancient Hindu shrine perched on top of an outcrop amidst constantly crashing waves.&nbsp;</span></p><p><br></p><p><span style=\"color: rgb(0, 0, 0);\">Then Begin your scenic transfer from the serene Ubud area to the lively, vibrant beaches of Kuta. The journey will take you through the lush landscapes of Bali, and upon arrival, you\'ll have time to explore Kuta\'s bustling streets, famous beaches, and exciting nightlife. The rest of the evening is yours to enjoy at leisure, whether you choose to relax on the beach, shop, or discover the many dining options available in Kuta. Overnight stay in the hotel.&nbsp;</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXeqsUrQwDYhD_3rcB9dMYnrnbXoFErtgMqa5zm-Gx3REe7viAcZMbTWGua9TILptPakbdcgGjSrlny7U_xAWp6DjFzLsZp81RwowMEsExuEP4t57D_bmX9ghtOaaIUu-2cMIMeSqFZb1MnquzL4h1Q?key=H-BwDgy9xr8m2oQBY7URfQ\" alt=\"2023 Tanah Lot Temple and Uluwatu Temple Tour with Shopping\" height=\"446.25434801052\" width=\"669.7836468668341\"></span></p><p><br></p><p><strong style=\"color: rgb(0, 0, 0);\">DAY 6: NUSA PENIDA DAY TOUR</strong></p><p><span style=\"color: rgb(0, 0, 0);\">After breakfast, it’s a full day of beach hopping. It is an exotic and still virgin charming island nestled in the waters between Bali and Lombok has slowly but surely become a favorite with travelers for its beautiful beaches, rugged coastline and relaxed way of life. Overnight stay in a hotel.</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXft1vvi-ulf_xfUlxpcnYTSO26ixUIiwb9ktAK1xhP8UwWeKh5iYBwR1OO9eLSNrcl7-zup-homW4wCuf015cuSf7tSWGjHogoc5XTBmOwpVGaB0P1RVVRUPHehAi03sfcxH3CQjF7G-VAHAzUNEaU?key=H-BwDgy9xr8m2oQBY7URfQ\" alt=\"West Nusa Penida Full Day Tour - Inclusive Bali Tour\" height=\"281.60213578940545\" width=\"669\"></span></p><p><br></p><p><strong style=\"color: rgb(0, 0, 0);\">DAY 7: FULL DAY TOUR OF WATER SPORTS ULUWATU TEMPLE WITH KECAK DANCE</strong></p><p><span style=\"color: rgb(0, 0, 0);\">After breakfast, proceed to experience exciting Water Sports (banana boat, jet ski, parasailing), Nusa Dua Peninsula Island and Uluwatu Temple.Tanjung Benoa Water Sports offers a huge variety of watersports, from&nbsp;</span><a href=\"http://www.tanjungbenoawatersports.com/activity/jet-ski/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 0, 0);\">jet ski,</a><span style=\"color: rgb(0, 0, 0);\">&nbsp;</span><a href=\"http://www.tanjungbenoawatersports.com/activity/parasailing/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 0, 0);\">parasailing,&nbsp;</a><a href=\"http://www.tanjungbenoawatersports.com/activity/snorkeling/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 0, 0);\">snorkeling</a><span style=\"color: rgb(0, 0, 0);\">, scuba diving,&nbsp;</span><a href=\"http://www.tanjungbenoawatersports.com/activity/sea-walker/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 0, 0);\">seawalker</a><span style=\"color: rgb(0, 0, 0);\">, fly board and your choice of water based activities is limitless. Later around 3pm and&nbsp; visit the famous Uluwatu Temple, Uluwatu Temple (Pura Luhur Uluwatu) is one of six key temples believed to be Bali\'s spiritual pillars, is renowned for its magnificent location, perched on top of a steep cliff approximately 70 metres above sea level. Overnight stay at the hotel.&nbsp;</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXdiIuseVV7l0BrDzeZRzLmr-BPTg5QEeObhYmr738msaJGxFKDka9kZoDYkoO200K-AP1KGWI_TwXWVLSrfk9eZmnj_-LRWM-zFAdNAEhIGBl_s-_JMaHNhijr6yMU7SFM8HzkOxK84C-82avOx0A?key=H-BwDgy9xr8m2oQBY7URfQ\" alt=\"Special Offer! Half-Day Tour: Uluwatu Temple and Kecak Fire Dance Show –  ENJOYKUTA.COM | Book Tours &amp; Things To Do in Bali\" height=\"371.930208390308\" width=\"669.7970584996145\"></span></p><p><br></p><p><strong style=\"color: rgb(0, 0, 0);\">DAY 8: DEPARTURE&nbsp;</strong></p><p><span style=\"color: rgb(0, 0, 0);\">After morning Breakfast time at leisure until checkout. After checkout proceeds to the airport for your flight back home with happy memories.</span></p><p><br></p><p><strong style=\"background-color: transparent; color: rgb(255, 0, 0);\">VISA &amp; MANDATORY DOCUMENTS</strong></p><ul><li><span style=\"background-color: transparent;\">&nbsp;A passport that is valid and still valid for at least 6 months</span></li><li><span style=\"background-color: transparent;\">A return flight ticket or a one-way ticket to continue the journey to another country</span></li><li><span style=\"background-color: transparent;\">&nbsp;It is also suggested to carry 2 passport size photographs (43mm x 55mm) taken against a white background.</span></li></ul><p><br></p><p><strong style=\"background-color: transparent; color: rgb(255, 0, 0);\">PAYMENT POLICY</strong></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Flight:</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">100% at the time of confirmation</span></p><p